class WalletKeysDesktopPopup extends ConsumerWidget {
  const WalletKeysDesktopPopup({
    super.key,
    required this.words,
    required this.walletId,
    this.clipboardInterface = const ClipboardWrapper(),
    this.keyData,
  });

  final List<String> words;
  final String walletId;
  final ClipboardInterface clipboardInterface;
  final KeyDataInterface? keyData;

  static const String routeName = "walletKeysDesktopPopup";

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return DesktopDialog(
      maxWidth: 614,
      maxHeight: double.infinity,
      child: Column(
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Padding(
                padding: const EdgeInsets.only(left: 32),
                child: Text(
                  keyData != null ? l10n.walletKeys : l10n.walletSeed,
                  style: STextStyles.desktopH3(context),
                ),
              ),
              DesktopDialogCloseButton(
                onPressedOverride: () {
                  Navigator.of(context, rootNavigator: true).pop();
                },
              ),
            ],
          ),
          const SizedBox(height: 6),
          keyData != null
              ? keyData is ViewOnlyWalletData
                    ? Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 16),
                        child: ViewOnlyWalletDataWidget(
                          data: keyData as ViewOnlyWalletData,
                        ),
                      )
                    : _Mnemonic(words: words, walletId: walletId)
              : _Mnemonic(words: words, walletId: walletId),
          const SizedBox(height: 32),
        ],
      ),
    );
  }
}

class _Mnemonic extends StatelessWidget {
  const _Mnemonic({required this.words, required this.walletId});

  final List<String> words;
  final String walletId;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(
          l10n.restoreRecoveryPhrase,
          style: STextStyles.desktopTextMedium(context),
        ),
        const SizedBox(height: 8),
        Center(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 32),
            child: Text(
              l10n.walletWriteDownDesktop,
              style: STextStyles.desktopTextExtraExtraSmall(context),
              textAlign: TextAlign.center,
            ),
          ),
        ),
        const SizedBox(height: 24),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: MnemonicTable(
            words: words,
            isDesktop: true,
            itemBorderColor: Theme.of(context)
                .extension<StackColors>()!
                .buttonBackSecondary,
          ),
        ),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: MnemonicPassphraseNote(walletId: walletId),
        ),
        const SizedBox(height: 24),
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 32),
          child: Row(
            children: [
              Expanded(
                child: SecondaryButton(
                  label: l10n.commonCopy,
                  onPressed: () async {
                    await const ClipboardWrapper().setSecret(words.join(" "));
                    if (context.mounted) {
                      unawaited(
                        showFloatingFlushBar(
                          type: FlushBarType.info,
                          message: l10n.commonCopiedToClipboard,
                          iconAsset: Assets.svg.copy,
                          context: context,
                        ),
                      );
                    }
                  },
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: PrimaryButton(
                  label: l10n.receiveShowQr,
                  onPressed: () {
                    // TODO: address utils
                    final String value = AddressUtils.encodeQRSeedData(words);
                    Navigator.of(context).pushNamed(
                      QRCodeDesktopPopupContent.routeName,
                      arguments: value,
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}
